pub fn word_freq(text: Str) -> Map[Str, Int] {
  let words = text.lower().split(" ").filter(fn(w) => not w.is_empty())
  let start: Map[Str, Int] = Map {}
  return words.fold(start, fn(m: Map[Str, Int], w: Str) -> Map[Str, Int] {
    match m.get(w) {
      Some(n) => { return m.set(w, n + 1) },
      None => { return m.set(w, 1) },
    }
  })
}
